import{_ as a,o as e,c as t,a4 as i}from"./chunks/framework.vNSRaLQv.js";const k=JSON.parse('{"title":"PVE VM 关机超时问题记录","description":"","frontmatter":{"title":"PVE VM 关机超时问题记录","date":"2026-09-03T00:00:00.000Z"},"headers":[],"relativePath":"posts/PVE_VM关机超时问题记录.md","filePath":"posts/PVE_VM关机超时问题记录.md"}'),n={name:"posts/PVE_VM关机超时问题记录.md"};function l(d,s,h,o,p,r){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="pve-vm-关机超时问题记录" tabindex="-1">PVE VM 关机超时问题记录 <a class="header-anchor" href="#pve-vm-关机超时问题记录" aria-label="Permalink to &quot;PVE VM 关机超时问题记录&quot;">​</a></h1><h2 id="现象" tabindex="-1">现象 <a class="header-anchor" href="#现象" aria-label="Permalink to &quot;现象&quot;">​</a></h2><p>在 Proxmox VE (PVE) 上对 VM 执行 <code>qm shutdown</code> 或 <code>qm reboot</code> 时，长时间等待后报错：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>TASK ERROR: VM quit/powerdown failed - got timeout</span></span></code></pre></div><h2 id="根本原因" tabindex="-1">根本原因 <a class="header-anchor" href="#根本原因" aria-label="Permalink to &quot;根本原因&quot;">​</a></h2><h3 id="_1-关机原理" tabindex="-1">1. 关机原理 <a class="header-anchor" href="#_1-关机原理" aria-label="Permalink to &quot;1. 关机原理&quot;">​</a></h3><ul><li><code>qm shutdown</code> 是通过 ACPI 信号通知 Guest 操作系统优雅关机</li><li>如果 VM 没有安装/运行 <code>qemu-guest-agent</code>，则依赖 Guest 内部的 ACPI 处理</li><li>对于 <strong>Ventoy 启动菜单</strong> 或 <strong>ISO 引导界面</strong>，Guest 操作系统尚未加载，没有 ACPI 响应能力</li><li>PVE 默认等待 <strong>10 分钟</strong> 后超时，返回上述错误</li></ul><h3 id="_2-相关配置" tabindex="-1">2. 相关配置 <a class="header-anchor" href="#_2-相关配置" aria-label="Permalink to &quot;2. 相关配置&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>-qm shutdown 流程：</span></span>
<span class="line"><span>  1. 发送 ACPI 信号给 QEMU</span></span>
<span class="line"><span>  2. QEMU 尝试通过 virtio-guest-agent 或直接 ACPI 通知 Guest</span></span>
<span class="line"><span>  3. Guest OS 响应并执行关机</span></span>
<span class="line"><span>  4. 超时（默认 10 分钟）则报 &quot;got timeout&quot;</span></span></code></pre></div><h2 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>命令</th><th>说明</th></tr></thead><tbody><tr><td>VM 在 Ventoy/ISO 启动菜单（未装系统）</td><td><code>qm stop 100</code></td><td>强制断电，等同拔电源</td></tr><tr><td>VM 在重装系统过程中</td><td><code>qm stop 100</code></td><td>同上</td></tr><tr><td>VM 已装好系统且已登录</td><td><code>qm shutdown 100</code></td><td>优雅关机，正常流程</td></tr><tr><td>需要强制重启</td><td><code>qm reset 100</code></td><td>等同于硬件复位</td></tr></tbody></table><h3 id="装好系统后补充" tabindex="-1">装好系统后补充 <a class="header-anchor" href="#装好系统后补充" aria-label="Permalink to &quot;装好系统后补充&quot;">​</a></h3><p>进入已安装的操作系统后，安装 <code>qemu-guest-agent</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># Debian/Ubuntu</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">apt</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> install</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> qemu-guest-agent</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">systemctl</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> enable</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> --now</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> qemu-guest-agent</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 配置 PVE VM 启用 agent</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">qm</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> set</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> &lt;</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;">vmi</span><span style="--shiki-light:#393A34;--shiki-dark:#DBD7CAEE;">d</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;">&gt;</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> --agent</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> enabled=</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;">1</span></span></code></pre></div><p>安装后 <code>qm shutdown</code> 会通过 guest-agent 触发系统级关机，速度更快、更安全。</p><h2 id="与停服操作无关" tabindex="-1">与停服操作无关 <a class="header-anchor" href="#与停服操作无关" aria-label="Permalink to &quot;与停服操作无关&quot;">​</a></h2><p>此问题与之前禁用 <code>corosync</code>、<code>pve-firewall</code> 等服务无关，是 PVE 的标准行为。</p><h2 id="时间线" tabindex="-1">时间线 <a class="header-anchor" href="#时间线" aria-label="Permalink to &quot;时间线&quot;">​</a></h2><ul><li>2026-09-03：重装 PVE 后多次触发此问题</li><li>根因：VM 在 Ventoy 引导界面执行 <code>qm shutdown</code>，Guest 无法响应</li><li>解决：改用 <code>qm stop</code> 强制断电</li></ul><hr><p><em>记录日期：2026-09-03</em><em>PVE 版本：9.2.2 / Debian 13 (trixie)</em></p>`,21)])])}const g=a(n,[["render",l]]);export{k as __pageData,g as default};
